from pathlib import Path


def replace_once(path: str, old: str, new: str):
    p = Path(path)
    text = p.read_text(encoding='utf-8')
    if old not in text:
        raise SystemExit(f'bloco nao encontrado em {path}: {old[:240]!r}')
    p.write_text(text.replace(old, new, 1), encoding='utf-8')

# Remove setCaptureRate: essa API coloca MediaRecorder em modo time-lapse e nao deve
# ser usada no pipeline de video HFR em tempo real.
rec = 'app/src/main/java/com/steadyvault/camera/capture/recorder/DirectMediaRecorderBackend.kt'
replace_once(rec, '''    private val targetFps: Int,\n    private val highSpeedCapture: Boolean,\n    private val videoMime: String,''', '''    private val targetFps: Int,\n    private val videoMime: String,''')
replace_once(rec, '''                setVideoSize(width, height)\n                // Constrained high-speed tem uma taxa de captura propria. Informar a\n                // mesma taxa ao MediaRecorder evita tratar os bursts como stream comum.\n                if (highSpeedCapture) setCaptureRate(targetFps.toDouble())\n                setVideoFrameRate(targetFps)''', '''                setVideoSize(width, height)\n                setVideoFrameRate(targetFps)''')

service = 'app/src/main/java/com/steadyvault/camera/capture/service/CaptureService.kt'
replace_once(service, '''            targetFps = cameraProfile.targetFps,\n            highSpeedCapture = cameraProfile.highSpeed,\n            videoMime = encoderProfile.mime,''', '''            targetFps = cameraProfile.targetFps,\n            videoMime = encoderProfile.mime,''')

# 120: se a HAL publica [120,120], tente sessao regular mesmo quando o min frame
# duration publico e conservador. Isso evita o batching de constrained high-speed.
replace_once(service, '''        val map = characteristics.get(CameraCharacteristics.SCALER_STREAM_CONFIGURATION_MAP) ?: return null\n        val minFrameNs = encoderSurfaceMinFrameDurationNs(map, size, preferMediaRecorder = true)\n        val targetFrameNs = frameDurationNs(targetFps)\n        if (minFrameNs > 0L && minFrameNs > targetFrameNs + HIGH_FPS_FRAME_TOLERANCE_NS) return null\n        return exact''', '''        if (targetFps == CaptureModeStore.FPS_120) return exact\n        val map = characteristics.get(CameraCharacteristics.SCALER_STREAM_CONFIGURATION_MAP) ?: return null\n        val minFrameNs = encoderSurfaceMinFrameDurationNs(map, size, preferMediaRecorder = true)\n        val targetFrameNs = frameDurationNs(targetFps)\n        if (minFrameNs > 0L && minFrameNs > targetFrameNs + HIGH_FPS_FRAME_TOLERANCE_NS) return null\n        return exact''')

# Se a camera logica selecionada nao oferecer o HFR, procure uma camera fisica do
# mesmo lado que ofereca exatamente a resolucao/FPS. 30/60 nunca entram aqui.
replace_once(service, '''        for ((size, fps) in configurationRequestOrder(targetFps)) {\n            if (fps != targetFps || size !in highSpeedSizes) continue\n            val fpsRange = resolveFpsRange(characteristics, size, fps, highSpeed = true) ?: continue\n            val profile = createCameraProfile(\n                cameraId = cameraId,\n                characteristics = characteristics,\n                videoSize = size,\n                targetFps = fps,\n                fpsRange = fpsRange,\n                highSpeed = true,\n                dynamicRangeProfile = dynamicRange\n            )\n            if (!matchesRequestedMode(profile, targetFps)) continue\n            val encoder = selectDirectRecorderEncoder(profile) ?: continue\n            if (profile.hasExactFpsRange()) return profile to encoder\n        }\n        return null\n    }''', '''        for ((size, fps) in configurationRequestOrder(targetFps)) {\n            if (fps != targetFps || size !in highSpeedSizes) continue\n            val fpsRange = resolveFpsRange(characteristics, size, fps, highSpeed = true) ?: continue\n            val profile = createCameraProfile(\n                cameraId = cameraId,\n                characteristics = characteristics,\n                videoSize = size,\n                targetFps = fps,\n                fpsRange = fpsRange,\n                highSpeed = true,\n                dynamicRangeProfile = dynamicRange\n            )\n            if (!matchesRequestedMode(profile, targetFps)) continue\n            val encoder = selectDirectRecorderEncoder(profile) ?: continue\n            if (profile.hasExactFpsRange()) return profile to encoder\n        }\n        return selectAlternateHighFpsConfiguration(targetFps, allowHdr)\n    }\n\n    private fun selectAlternateHighFpsConfiguration(\n        targetFps: Int,\n        allowHdr: Boolean\n    ): Pair<CameraProfile, EncoderProfile>? {\n        if (targetFps < CaptureModeStore.FPS_120 || allowHdr) return null\n        val selectedId = preferredCameraId ?: return null\n        val manager = getSystemService(CameraManager::class.java)\n        val selectedCharacteristics = runCatching { manager.getCameraCharacteristics(selectedId) }.getOrNull() ?: return null\n        val selectedFacing = selectedCharacteristics.get(CameraCharacteristics.LENS_FACING)\n        val requestedSize = recordingSettings.exactPreferredSize() ?: return null\n        val dynamicRange = standardDynamicRangeProfile()\n\n        val candidates = manager.cameraIdList.asSequence()\n            .filter { it != selectedId }\n            .mapNotNull { id ->\n                val c = runCatching { manager.getCameraCharacteristics(id) }.getOrNull() ?: return@mapNotNull null\n                if (c.get(CameraCharacteristics.LENS_FACING) != selectedFacing) return@mapNotNull null\n                id to c\n            }\n            .toList()\n\n        // Primeiro tente 120 regular na camera fisica. Depois constrained high-speed.\n        if (targetFps == CaptureModeStore.FPS_120) {\n            for ((id, c) in candidates) {\n                val regularRange = resolveRegularHighFpsRange(c, requestedSize, targetFps) ?: continue\n                val profile = createCameraProfile(\n                    cameraId = id, characteristics = c, videoSize = requestedSize,\n                    targetFps = targetFps, fpsRange = regularRange, highSpeed = false,\n                    dynamicRangeProfile = dynamicRange\n                )\n                val encoder = selectDirectRecorderEncoder(profile) ?: continue\n                if (matchesRequestedMode(profile, targetFps)) return profile to encoder\n            }\n        }\n\n        for ((id, c) in candidates) {\n            val map = c.get(CameraCharacteristics.SCALER_STREAM_CONFIGURATION_MAP) ?: continue\n            val sizes = runCatching { map.highSpeedVideoSizes?.toSet().orEmpty() }.getOrDefault(emptySet())\n            if (requestedSize !in sizes) continue\n            val range = resolveFpsRange(c, requestedSize, targetFps, highSpeed = true) ?: continue\n            val profile = createCameraProfile(\n                cameraId = id, characteristics = c, videoSize = requestedSize,\n                targetFps = targetFps, fpsRange = range, highSpeed = true,\n                dynamicRangeProfile = dynamicRange\n            )\n            val encoder = selectDirectRecorderEncoder(profile) ?: continue\n            if (profile.hasExactFpsRange() && matchesRequestedMode(profile, targetFps)) return profile to encoder\n        }\n        return null\n    }''')

# Permite reutilizar/cachear uma camera fisica traseira para HFR, mas continua
# exigindo exatamente a camera selecionada em 30/60 e na selfie.
replace_once(service, '''    private fun preferredCameraCompatible(profile: CameraProfile): Boolean {\n        val selected = preferredCameraId ?: return true\n        return profile.cameraId == selected\n    }''', '''    private fun preferredCameraCompatible(profile: CameraProfile): Boolean {\n        val selected = preferredCameraId ?: return true\n        if (profile.cameraId == selected) return true\n        if (profile.targetFps < CaptureModeStore.FPS_120) return false\n        val manager = getSystemService(CameraManager::class.java)\n        val selectedFacing = runCatching {\n            manager.getCameraCharacteristics(selected).get(CameraCharacteristics.LENS_FACING)\n        }.getOrNull() ?: return false\n        val profileFacing = runCatching {\n            manager.getCameraCharacteristics(profile.cameraId).get(CameraCharacteristics.LENS_FACING)\n        }.getOrNull() ?: return false\n        return selectedFacing == CameraCharacteristics.LENS_FACING_BACK && profileFacing == selectedFacing\n    }''')

# Constrained high-speed: request minimo para priorizar cadence. Estabilizacao volta
# a ser aplicada normalmente nos modos 30/60.
old_stab = '''        // O Camera2 documenta OIS como controle válido também no modo high-speed.\n        // EIS/preview stabilization são best-effort: só são enviados quando a câmera\n        // publica explicitamente o modo. OFF permanece o fallback mais previsível.\n        val videoModes = profile.characteristics.get(\n            CameraCharacteristics.CONTROL_AVAILABLE_VIDEO_STABILIZATION_MODES\n        ) ?: intArrayOf()\n        val requestedStabilization = recordingSettings.stabilization\n        val autoUseOis = requestedStabilization == CaptureSettings.STABILIZATION_AUTO && profile.oisSupported\n        val explicitOis = requestedStabilization == CaptureSettings.STABILIZATION_OIS\n        val explicitEis = requestedStabilization == CaptureSettings.STABILIZATION_EIS\n        val explicitPreview = requestedStabilization == CaptureSettings.STABILIZATION_PREVIEW\n        when {\n            (autoUseOis || explicitOis) && profile.oisSupported -> {\n                setSafely(builder, CaptureRequest.CONTROL_VIDEO_STABILIZATION_MODE, CameraMetadata.CONTROL_VIDEO_STABILIZATION_MODE_OFF)\n                OpticalStabilizationCapability.apply(builder, profile.oisCapability, enabled = true)\n            }\n            explicitEis && videoModes.contains(CameraMetadata.CONTROL_VIDEO_STABILIZATION_MODE_ON) -> {\n                OpticalStabilizationCapability.apply(builder, profile.oisCapability, enabled = false)\n                setSafely(builder, CaptureRequest.CONTROL_VIDEO_STABILIZATION_MODE, CameraMetadata.CONTROL_VIDEO_STABILIZATION_MODE_ON)\n            }\n            explicitPreview && Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU &&\n                videoModes.contains(CameraMetadata.CONTROL_VIDEO_STABILIZATION_MODE_PREVIEW_STABILIZATION) -> {\n                OpticalStabilizationCapability.apply(builder, profile.oisCapability, enabled = false)\n                setSafely(builder, CaptureRequest.CONTROL_VIDEO_STABILIZATION_MODE, CameraMetadata.CONTROL_VIDEO_STABILIZATION_MODE_PREVIEW_STABILIZATION)\n            }\n            else -> {\n                setSafely(builder, CaptureRequest.CONTROL_VIDEO_STABILIZATION_MODE, CameraMetadata.CONTROL_VIDEO_STABILIZATION_MODE_OFF)\n                OpticalStabilizationCapability.apply(builder, profile.oisCapability, enabled = false)\n            }\n        }'''
new_stab = '''        // HFR prioriza cadence: constrained high-speed recebe o request minimo.\n        // OIS/EIS/preview stabilization permanecem disponíveis normalmente em 30/60.\n        setSafely(\n            builder,\n            CaptureRequest.CONTROL_VIDEO_STABILIZATION_MODE,\n            CameraMetadata.CONTROL_VIDEO_STABILIZATION_MODE_OFF\n        )\n        OpticalStabilizationCapability.apply(builder, profile.oisCapability, enabled = false)'''
replace_once(service, old_stab, new_stab)

# A resolucao HFR deve considerar todas as cameras traseiras, nao apenas a logica.
old_cache = '''        val cachedMatrix = CaptureCapabilityMatrix.cached(this)?.forCamera(cameraId)\n        val catalogResolution = CaptureModeCatalog.preferredResolution(\n            context = this,\n            fps = targetFps,\n            requestedResolution = storedResolution,\n            matrix = cachedMatrix\n        )'''
new_cache = '''        val fullMatrix = CaptureCapabilityMatrix.cached(this)\n        val selectedOption = CameraLensCatalog.options(this).firstOrNull { it.id == cameraId }\n        val cachedMatrix = if (targetFps >= CaptureModeStore.FPS_120 && selectedOption?.isBack == true) {\n            val backIds = CameraLensCatalog.options(this).filter { it.isBack }.mapTo(mutableSetOf()) { it.id }\n            fullMatrix?.copy(\n                modes = fullMatrix.modes.filter { it.cameraId in backIds },\n                cameras = fullMatrix.cameras.filter { it.cameraId in backIds }\n            )\n        } else {\n            fullMatrix?.forCamera(cameraId)\n        }\n        val catalogResolution = CaptureModeCatalog.preferredResolution(\n            context = this,\n            fps = targetFps,\n            requestedResolution = storedResolution,\n            matrix = cachedMatrix\n        )'''
replace_once(service, old_cache, new_cache)

# UI: para a traseira, HFR pode vir de uma camera fisica invisivel ao seletor.
activity = 'app/src/main/java/com/steadyvault/camera/ui/capture/CaptureActivity.kt'
replace_once(activity, '''    private fun selectedCapabilityMatrix(): CaptureCapabilityMatrix.Matrix? {\n        val matrix = capabilityMatrix ?: return null\n        val selectedId = CaptureSettings.snapshot(this).selectedCameraId\n        if (selectedId != null) return matrix.forCamera(selectedId)\n        val allowedIds = cameraOptions.filter { it.isBack }.mapTo(mutableSetOf()) { it.id }\n        return matrix.copy(\n            modes = matrix.modes.filter { it.cameraId in allowedIds },\n            cameras = matrix.cameras.filter { it.cameraId in allowedIds }\n        )\n    }''', '''    private fun selectedCapabilityMatrix(): CaptureCapabilityMatrix.Matrix? {\n        val matrix = capabilityMatrix ?: return null\n        val selectedId = CaptureSettings.snapshot(this).selectedCameraId\n        val allOptions = CameraLensCatalog.options(this)\n        val selectedOption = allOptions.firstOrNull { it.id == selectedId }\n        if (selectedOption?.isFront == true) return matrix.forCamera(selectedId)\n        val allowedIds = allOptions.filter { it.isBack }.mapTo(mutableSetOf()) { it.id }\n        if (allowedIds.isEmpty() && selectedId != null) return matrix.forCamera(selectedId)\n        return matrix.copy(\n            modes = matrix.modes.filter { it.cameraId in allowedIds },\n            cameras = matrix.cameras.filter { it.cameraId in allowedIds }\n        )\n    }''')

# Nao ressuscitar job SUCCESS/SKIPPED/ERROR ao publicar o ultimo progresso.
queue = 'app/src/main/java/com/steadyvault/camera/processing/auto/AutoGapRepairQueueStore.kt'
replace_once(queue, '''    fun updateProgress(context: Context, id: String, progress: Int, message: String): Job? = update(context, id) {\n        it.copy(status = Status.RUNNING, progress = progress.coerceIn(0, 100), message = message, updatedAtMs = System.currentTimeMillis())\n    }''', '''    fun updateProgress(context: Context, id: String, progress: Int, message: String): Job? = update(context, id) {\n        if (it.status != Status.RUNNING) it\n        else it.copy(\n            progress = progress.coerceIn(0, 100),\n            message = message,\n            updatedAtMs = System.currentTimeMillis()\n        )\n    }''')

print('final HFR/vault patch applied')
